lessons.solution:
func Clamp(n, low, high int) int {
	if n < low {
		return low
	}
	if n > high {
		return high
	}
	return n
}

func SafeDivide(n, d int) (int, bool) {
	if d == 0 {
		return 0, false
	}
	return n / d, true
}

func SumTo(n int) int {
	total := 0
	for i := 1; i <= n; i++ {
		total += i
	}
	return total
}

func Digits(n int) int {
	if n == 0 {
		return 1
	}
	count := 0
	for n > 0 {
		count++
		n /= 10
	}
	return count
}

func GCD(a, b int) int {
	for b != 0 {
		a, b = b, a%b
	}
	return a
}

func DigitSum(n int) int {
	total := 0
	for n > 0 {
		total += n % 10
		n /= 10
	}
	return total
}

func CanReach(values []int) bool {
	if len(values) == 0 {
		return false
	}
	farthest := 0
	for i, step := range values {
		if i > farthest {
			return false
		}
		if i+step > farthest {
			farthest = i + step
		}
		if farthest >= len(values)-1 {
			return true
		}
	}
	return false
}

