lessons.solution:
func UpperASCII(s string) string {
	out := []rune(s)
	for i, r := range out {
		if r >= 'a' && r <= 'z' {
			out[i] = r - ('a' - 'A')
		}
	}
	return string(out)
}

func ReplaceFirst(values []int, x int) []int {
	out := append([]int{}, values...)
	if len(out) > 0 {
		out[0] = x
	}
	return out
}

func Positive(values []int) []int {
	out := []int{}
	for _, n := range values {
		if n > 0 {
			out = append(out, n)
		}
	}
	return out
}

func Chunks(values []int, size int) [][]int {
	out := [][]int{}
	if size <= 0 {
		return out
	}
	for start := 0; start < len(values); start += size {
		end := start + size
		if end > len(values) {
			end = len(values)
		}
		out = append(out, append([]int{}, values[start:end]...))
	}
	return out
}

func RotateLeft(values []int, k int) []int {
	n := len(values)
	out := make([]int, n)
	if n == 0 {
		return out
	}
	k %= n
	for i := range out {
		out[i] = values[(i+k)%n]
	}
	return out
}

