func Subsequence(wanted, text string) bool {
	p := []rune(wanted)
	i := 0
	for _, r := range text {
		if i < len(p) && r == p[i] {
			i++
		}
	}
	return i == len(p)
}

func RLE(s string) string {
	out := ""
	for i := 0; i < len(s); {
		j := i + 1
		for j < len(s) && s[j] == s[i] {
			j++
		}
		out += string(s[i]) + strconv.Itoa(j-i)
		i = j
	}
	return out
}

