func Prime(n int) bool {
	if n < 2 {
		return false
	}
	for d := 2; d <= n/d; d++ {
		if n%d == 0 {
			return false
		}
	}
	return true
}

func Base(n, base int) string {
	if n == 0 {
		return "0"
	}
	digits := "0123456789abcdef"
	out := ""
	for n > 0 {
		out = string(digits[n%base]) + out
		n /= base
	}
	return out
}

func RPN(s string) int {
	stack := []int{}
	for _, token := range strings.Fields(s) {
		n, err := strconv.Atoi(token)
		if err == nil {
			stack = append(stack, n)
			continue
		}
		b, a := stack[len(stack)-1], stack[len(stack)-2]
		stack = stack[:len(stack)-2]
		var result int
		switch token {
		case "+":
			result = a + b
		case "-":
			result = a - b
		case "*":
			result = a * b
		}
		stack = append(stack, result)
	}
	return stack[0]
}

func OptionMask(s string) uint {
	var mask uint
	for _, r := range s {
		mask |= uint(1) << uint(r-'a')
	}
	return mask
}

func Tape(program string) int {
	pairs := map[int]int{}
	stack := []int{}
	for i := 0; i < len(program); i++ {
		if program[i] == '[' {
			stack = append(stack, i)
		}
		if program[i] == ']' {
			open := stack[len(stack)-1]
			stack = stack[:len(stack)-1]
			pairs[open] = i
			pairs[i] = open
		}
	}
	cells := [8]byte{}
	ptr := 0
	for pc := 0; pc < len(program); pc++ {
		switch program[pc] {
		case '+':
			cells[ptr]++
		case '-':
			cells[ptr]--
		case '>':
			ptr++
		case '<':
			ptr--
		case '[':
			if cells[ptr] == 0 {
				pc = pairs[pc]
			}
		case ']':
			if cells[ptr] != 0 {
				pc = pairs[pc]
			}
		}
	}
	return int(cells[ptr])
}
